-- Leve classes with a classPath but no flags (propertyFlags 0, eventConditions NULL) are
-- untargetable on the client. Copy flags and event conditions from a field class (21xxxxx) that
-- uses the same client script.
UPDATE gamedata_actor_class t
JOIN (SELECT classPath, MIN(id) AS sid FROM gamedata_actor_class
      WHERE id BETWEEN 2100000 AND 2199999 AND propertyFlags <> 0 AND classPath <> '' GROUP BY classPath) m
  ON m.classPath = t.classPath
JOIN gamedata_actor_class s ON s.id = m.sid
SET t.propertyFlags = s.propertyFlags, t.eventConditions = s.eventConditions
WHERE t.id BETWEEN 2200000 AND 2299999 AND t.propertyFlags = 0 AND t.classPath <> '';
-- Fallback for classes whose script no field class uses: take the flags from a class in the same
-- monster family folder (/Chara/Npc/Monster/<Family>/...).
UPDATE gamedata_actor_class t
JOIN (SELECT SUBSTRING_INDEX(classPath, '/', 5) AS fam, MIN(id) AS sid FROM gamedata_actor_class
      WHERE propertyFlags <> 0 AND classPath LIKE '/Chara/Npc/Monster/%' GROUP BY fam) m
  ON m.fam = SUBSTRING_INDEX(t.classPath, '/', 5)
JOIN gamedata_actor_class s ON s.id = m.sid
SET t.propertyFlags = s.propertyFlags, t.eventConditions = s.eventConditions
WHERE t.id BETWEEN 2200000 AND 2299999 AND t.propertyFlags = 0 AND t.classPath LIKE '/Chara/Npc/Monster/%';
